package com.therighthon.rnr.client;
import com.therighthon.rnr.common.RNRPlayerData; import com.therighthon.rnr.common.RNRTags; import net.minecraft.client.Minecraft; import net.minecraft.client.gui.GuiGraphics; import net.minecraft.resources.ResourceLocation; import net.minecraft.world.InteractionHand; import net.minecraft.world.entity.player.Player; import net.minecraftforge.client.event.RegisterGuiOverlaysEvent; import net.minecraftforge.client.gui.overlay.ForgeGui; import net.minecraftforge.client.gui.overlay.IGuiOverlay;
public enum IngameOverlays { MATTOCK(IngameOverlays::render); final String id; final IGuiOverlay overlay; IngameOverlays(IGuiOverlay o){id=name().toLowerCase();overlay=o;} static final ResourceLocation TEXTURE=new ResourceLocation("rnr","textures/gui/icons/overlay.png"); public static void registerOverlays(RegisterGuiOverlaysEvent e){e.registerAboveAll(MATTOCK.id,MATTOCK.overlay);} private static void render(ForgeGui gui,GuiGraphics g,float pt,int w,int h){Minecraft mc=Minecraft.getInstance();Player p=mc.player;if(p!=null&&!mc.options.hideGui&&p.getItemInHand(InteractionHand.MAIN_HAND).is(RNRTags.Items.MATTOCKS)){g.drawString(mc.font,RNRPlayerData.getMode(p).getSerializedName(),w/2+100,h-20,0xFFFFFF);}}
}
